mapper.select:
select mc.cart_id as cartId, mc.account_id as accountId, a.nick_name as accountNickName, a.mobile as accountMobile, mc.product_id as productId, mp.product_name as productName, mc.sku_id as skuId, mps.sku_name as skuName, mc.quantity as quantity, mc.del_flag as delFlag, mc.create_time as createTime, mc.update_time as updateTime from mall_cart mc left join account a on mc.account_id = a.account_id and a.del_flag = 0 left join mall_product mp on mc.product_id = mp.product_id and mp.del_flag = 0 left join mall_product_sku mps on mc.sku_id = mps.sku_id and mps.del_flag = 0 where mc.del_flag = 0
and mc.account_id = #{accountId}
and a.nick_name like concat('%', #{accountNickName}, '%')
and a.mobile like concat('%', #{accountMobile}, '%')
and mc.product_id = #{productId}
and mp.product_name like concat('%', #{productName}, '%')
and mc.sku_id = #{skuId}
and mps.sku_name like concat('%', #{skuName}, '%')
order by mc.cart_id desc

select count(1)
from mall_cart mc
where mc.del_flag = 0

    and mc.account_id = #{accountId}


    and mc.product_id = #{productId}


    and mc.sku_id = #{skuId}

select mc.cart_id, mc.account_id, mc.product_id, mc.sku_id, mc.quantity, mc.del_flag, mc.create_time, mc.update_time from mall_cart mc where mc.del_flag = 0
and mc.account_id = #{accountId}
and mc.product_id = #{productId}
and mc.sku_id = #{skuId}
order by mc.cart_id desc limit 1

mapper.update:
update mall_cart
set del_flag = 1
where cart_id = #{cartId}
